import csv, io, re

data = open('/app/fpbase_proteins.csv').read()
fpbase = {row['slug']: row for row in csv.DictReader(io.StringIO(data))}

pdb_data = open('/app/pdb_fasta_all.txt').read()
entries = {}
h, s = None, []
for line in pdb_data.strip().split('\n'):
    if line.startswith('>'):
        if h: entries.setdefault(h[1:5], []).append(''.join(s))
        h, s = line, []
    else: s.append(line.strip())
if h: entries.setdefault(h[1:5], []).append(''.join(s))

flag = "DYKDDDDK"
clover = fpbase['clover']['seq'][1:]
gb = open('/app/plasmid.gb').read()
dhfr = re.search(r'/translation="([^"]+)"', gb.replace('\n', ' ')).group(1).replace(' ', '')[1:]
mcherry = fpbase['mcherry']['seq'][1:]
mgmt = entries['3KZY'][0]
lnk = "GGGGSGGGGS"
fusion = flag + lnk + clover + lnk + dhfr + lnk + mcherry + lnk + mgmt

ct = {
    'A': ['GCC', 'GCG', 'GCT', 'GCA'], 'R': ['CGG', 'CGC', 'AGG', 'CGT', 'CGA', 'AGA'],
    'N': ['AAC', 'AAT'], 'D': ['GAC', 'GAT'], 'C': ['TGC', 'TGT'],
    'Q': ['CAG', 'CAA'], 'E': ['GAG', 'GAA'], 'G': ['GGG', 'GGC', 'GGT', 'GGA'],
    'H': ['CAC', 'CAT'], 'I': ['ATC', 'ATT', 'ATA'],
    'L': ['CTG', 'CTC', 'CTT', 'CTA', 'TTG', 'TTA'], 'K': ['AAG', 'AAA'],
    'M': ['ATG'], 'F': ['TTC', 'TTT'], 'P': ['CCC', 'CCG', 'CCT', 'CCA'],
    'S': ['AGC', 'TCC', 'TCG', 'TCT', 'AGT', 'TCA'], 'T': ['ACC', 'ACG', 'ACT', 'ACA'],
    'W': ['TGG'], 'Y': ['TAC', 'TAT'], 'V': ['GTC', 'GTG', 'GTT', 'GTA'],
}

def gc(s): return sum(1 for c in s if c in 'GC')

dna = []
for i, aa in enumerate(fusion):
    best, best_pen = None, 999
    for codon in ct[aa]:
        temp = ''.join(dna) + codon
        L = len(temp)
        pen = 0
        for start in range(max(0, L - 50), L - 49):
            if start >= 0 and start + 50 <= L:
                g = gc(temp[start:start+50])
                pen += (15 - g)**2 if g < 15 else ((g - 35)**2 if g > 35 else 0)
        if pen == 0:
            best = codon
            break
        if pen < best_pen:
            best_pen, best = pen, codon
    dna.append(best)

dna_seq = ''.join(dna)

for iteration in range(50):
    bad = [i for i in range(len(dna_seq) - 49) if gc(dna_seq[i:i+50]) < 15 or gc(dna_seq[i:i+50]) > 35]
    if not bad:
        print(f"GC fixed after {iteration} iterations")
        break
    fixed = False
    for pos in bad:
        for cp in range(pos // 3, (pos + 50) // 3 + 1):
            if cp >= len(fusion): continue
            aa = fusion[cp]
            cur = dna_seq[3*cp:3*cp+3]
            for nc in ct[aa]:
                if nc == cur: continue
                nd = dna_seq[:3*cp] + nc + dna_seq[3*cp+3:]
                g = gc(nd[pos:pos+50])
                if 15 <= g <= 35:
                    ok = True
                    for s2 in range(max(0, pos - 49), min(pos + 50, len(nd) - 49)):
                        if s2 + 50 <= len(nd):
                            w = gc(nd[s2:s2+50])
                            if w < 15 or w > 35:
                                ok = False
                                break
                    if ok:
                        dna_seq = nd
                        fixed = True
                        break
            if fixed: break
        if fixed: break
    if not fixed:
        print(f"Could not fix all GC violations after iteration {iteration}")
        break

gc_code = {'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L','ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V','TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P','ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A','TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q','AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E','TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R','AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
tr = ''.join(gc_code[dna_seq[i:i+3]] for i in range(0, len(dna_seq), 3))

print(f"Length: {len(dna_seq)} nt (max 3000: {'PASS' if len(dna_seq) <= 3000 else 'FAIL'})")
bad = [(i, gc(dna_seq[i:i+50])) for i in range(len(dna_seq) - 49) if gc(dna_seq[i:i+50]) < 15 or gc(dna_seq[i:i+50]) > 35]
print(f"GC windows: {'PASS' if not bad else 'FAIL'} ({len(bad)} violations)")
for p, g in bad[:5]: print(f"  pos {p}: GC={g}/50")
print(f"Translation matches: {'PASS' if tr == fusion else 'FAIL'}")
print(f"No stop codons: {'PASS' if '*' not in tr else 'FAIL'}")
print(f"No start codon: {'PASS' if dna_seq[:3] != 'ATG' else 'FAIL'}")
print(f"No stop at end: {'PASS' if dna_seq[-3:] not in ['TAA','TAG','TGA'] else 'FAIL'}")
print(f"Spectra: Clover ex={fpbase['clover']['states.0.ex_max']} mCherry em={fpbase['mcherry']['states.0.em_max']}")

with open('/app/gblock.txt', 'w') as f:
    f.write(dna_seq)
print(f"Written {len(dna_seq)} nt to /app/gblock.txt")
